orders = [
    {"order_id": 1, "customer": {"id": 8, "address": {"city": "Lisbon"}}, "items": [{"sku": "P1", "qty": 2}, {"sku": "P2", "qty": 1}]},
    {"order_id": 2, "customer": {"id": 9, "address": None}, "items": [{"sku": "P1", "qty": 1}]},
    {"order_id": 3, "customer": {"id": 8}, "items": []},
]

def dig(data, path, default=None):
    for key in path.split("."):
        if isinstance(data, dict) and key in data:
            data = data[key]
        else:
            return default
    return data

for order in orders:
    print(dig(order, "customer.address.city", "unknown"))

