independent.solution:
REQUIRED = {"order_id": int, "amount_cents": int, "status": str}
batch = [
    {"order_id": 1, "amount_cents": 1990, "status": "paid"},
    {"order_id": 2, "amount_cents": "700", "status": "paid"},
    {"order_id": 3, "amount_cents": 500},
    {"order_id": 4, "amount_cents": 800, "status": "paid", "channel": "web"},
    {"order_id": 5, "amount_cents": 19.9, "status": "refunded"},
]

def issues(record):
    found = []
    for name, kind in REQUIRED.items():
        if name not in record:
            found.append(f"missing: {name}")
        elif type(record[name]) is not kind:
            found.append(f"type: {name} is {type(record[name]).__name__}")
    for name in sorted(set(record) - set(REQUIRED)):
        found.append(f"unknown: {name}")
    return found

clean = []
for record in batch:
    found = issues(record)
    if found:
        print(f"{record['order_id']}: {'; '.join(found)}")
    else:
        clean.append(record["order_id"])
print("clean:", clean)
